names2 = ['box', 'red box', 'tool box', 'toolbox', 'tape', 'tape roll', 'white tape', 'drill', 'clamp', 'ruler', 'scissors', 'container', 'basket', 'tray', 'bin', 'red block']
for n in names2:
    rr = primitives.call(name='submit_capx_action', action='get_object_pose', native_api=True, parameters={'object_name': n, 'return_bbox_extent': True})
    vals = rr.output['native_api_result']
    line = []
    for item in vals[:3]:
        if item:
            line.append(str(item.get('values'))[:110])
        else:
            line.append('None')
    print(n, '|', ' ; '.join(line))

